package dev.aster.charts;

import android.content.Context;
import android.os.*;
import android.widget.LinearLayout;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.function.Consumer;

/** Bounded real3-View operation across background/foreground and recreation.
 * Session contains data only, never an Activity/engine/view reference.
 */
final class NativeSoak {
    private static Session session;private Session own;
    private static final class Session {long start,duration,ticks,appends,corrections,prepares,cancelled,stale,callbacks,created,closed,heartbeatMax;int generations;final JSONArray samples=new JSONArray(),events=new JSONArray(),jobs=new JSONArray(),errors=new JSONArray();final ArrayList<Double> latencies=new ArrayList<>();}
    private final Handler handler=new Handler(Looper.getMainLooper());private final AsterEngine[] engines=new AsterEngine[3];private final AsterChartView[] views=new AsterChartView[3];private final boolean[] busy=new boolean[3];
    private Context context;private LinearLayout host;private AsterEngine diagnosticEngine;private Consumer<JSONObject> completion;private boolean running,foreground=true,finishing;private long previousBeat,lastSample,lastPrepare;private int cycle,generation;
    void run(Context context,LinearLayout host,AsterEngine diagnosticEngine,long durationMillis,Consumer<JSONObject> completion){this.context=context;this.host=host;this.diagnosticEngine=diagnosticEngine;this.completion=completion;try{if(session==null||SystemClock.elapsedRealtime()-session.start>=session.duration){session=new Session();session.start=SystemClock.elapsedRealtime();session.duration=durationMillis;}own=session;if(durationMillis<180000||durationMillis>900000)throw new IllegalArgumentException("Soak duration180000..900000ms");own.generations++;generation=own.generations;event("generation-start");for(int i=0;i<3;i++){engines[i]=new AsterEngine(context,4096,PrepareVerification.options());PrepareVerification.indicators(engines[i]);engines[i].scene(360,200);views[i]=new AsterChartView(context,engines[i]);host.addView(views[i],new LinearLayout.LayoutParams(-1,0,1));own.created++;}running=true;previousBeat=System.nanoTime();lastPrepare=lastSample=SystemClock.elapsedRealtime();handler.post(beat);handler.post(tick);sample("start");}catch(Throwable error){finish(error,"failed");}}
    void lifecycle(String kind){if(context==null)return;if(kind.equals("pause")||kind.equals("stop"))foreground=false;if(kind.equals("resume"))foreground=true;try{event(kind);}catch(JSONException error){finish(error,"failed");}}
    void stop(){if(context!=null)finish(null,"activity-destroyed");}
    private void event(String kind) throws JSONException {own.events.put(new JSONObject().put("atMs",SystemClock.elapsedRealtime()-own.start).put("event",kind).put("generation",generation));}
    private final Runnable beat=new Runnable(){@Override public void run(){if(!running)return;long now=System.nanoTime();if(foreground)own.heartbeatMax=Math.max(own.heartbeatMax,now-previousBeat);previousBeat=now;handler.postDelayed(this,16);}};
    private final Runnable tick=new Runnable(){@Override public void run(){if(!running)return;try{long now=SystemClock.elapsedRealtime();if(now-own.start>=own.duration){finish(null,"completed");return;}own.ticks++;for(int i=0;i<3;i++)if(!busy[i]){long start=System.nanoTime();JSONObject last=((JSONObject)engines[i].command("inspect")).getJSONObject("lastBar"),bar=new JSONObject(last.toString());double open=last.getDouble("close"),close=open+(own.ticks%5-2)*0.02;bar.put("time",last.getLong("time")+60000).put("open",open).put("close",close).put("high",Math.max(open,close)+0.2).put("low",Math.min(open,close)-0.2).put("volume",100+own.ticks%900);engines[i].applyDataEvent(new JSONObject().put("kind","append").put("bar",bar));own.appends++;if(own.ticks%30==0){engines[i].applyDataEvent((JSONObject)engines[i].invoke("nativeBenchmarkEvent",0));own.corrections++;}engines[i].scene(Math.max(100,views[i].getWidth()/context.getResources().getDisplayMetrics().density),Math.max(80,views[i].getHeight()/context.getResources().getDisplayMetrics().density));if(views[i].lastError!=null)throw new AssertionError(views[i].lastError);if(own.latencies.size()==2000)own.latencies.remove(0);own.latencies.add((System.nanoTime()-start)/1e6);}if(now-lastPrepare>=8000){lastPrepare=now;prepare(cycle++%3);}if(now-lastSample>=10000){lastSample=now;sample("operating");}handler.postDelayed(this,100);}catch(Throwable error){finish(error,"failed");}}};
    private void prepare(int index) throws JSONException {if(busy[index])return;busy[index]=true;int mode=cycle%3;AsterEngine source=engines[index];own.prepares++;final AsterEngine.AsyncJob[] job={null};job[0]=source.prepareSeededAsync(mode==0?8192:4096,42,200,new AsterEngine.AsyncOptions(30000,256),new AsterEngine.AsyncListener(){@Override public void onProgress(AsterEngine.AsyncProgress value){if(mode==1&&value.phase.equals("ready"))job[0].cancel();}@Override public void onComplete(AsterEngine.AsyncResult result){try{own.callbacks++;own.jobs.put(new JSONObject().put("atMs",SystemClock.elapsedRealtime()-own.start).put("generation",generation).put("chart",index).put("expectedMode",mode).put("result",result.toJSON()));if(!running)return;busy[index]=false;boolean expected=mode==0?result.succeeded():mode==1?result.status.equals("cancelled"):result.status.equals("stale");if(!expected)throw new AssertionError("Soak prepare mode"+mode+" status"+result.status);if(mode==1)own.cancelled++;if(mode==2)own.stale++;sample("prepared");}catch(Throwable error){finish(error,"failed");}}});if(mode==2){source.applyDataEvent((JSONObject)source.invoke("nativeBenchmarkEvent",0));own.corrections++;}}
    private void sample(String phase) throws JSONException {Debug.MemoryInfo info=new Debug.MemoryInfo();Debug.getMemoryInfo(info);JSONObject sample=new JSONObject().put("atMs",SystemClock.elapsedRealtime()-own.start).put("generation",generation).put("phase",phase).put("pssKiB",info.getTotalPss()).put("rssKiB",rss()).put("processRuntime",diagnosticEngine.runtimeMetrics());JSONArray models=new JSONArray();for(int i=0;i<3;i++)if(engines[i]!=null)models.put(new JSONObject().put("chart",i).put("bars",((JSONObject)engines[i].command("inspect")).getInt("storedBars")).put("runtime",engines[i].runtimeMetrics()).put("renderedRevision",views[i].renderedRevision).put("engineRevision",engines[i].revision()).put("viewWidthPx",views[i].getWidth()).put("viewHeightPx",views[i].getHeight()).put("viewError",views[i].lastError==null?JSONObject.NULL:views[i].lastError));sample.put("charts",models);own.samples.put(sample);write("android-soak-progress.json",report("operating",null).toString());}
    private long rss(){try(BufferedReader in=new BufferedReader(new FileReader("/proc/self/status"))){String line;while((line=in.readLine())!=null)if(line.startsWith("VmRSS:"))return Long.parseLong(line.substring(6).trim().split("\\s+")[0]);}catch(IOException|NumberFormatException ignored){}return 0;}
    private JSONObject trend() throws JSONException {double n=0,sx=0,sy=0,sxx=0,sxy=0;long start=0,end=0,peak=0;for(int i=0;i<own.samples.length();i++){JSONObject s=own.samples.getJSONObject(i);long at=s.getLong("atMs"),pss=s.getLong("pssKiB");peak=Math.max(peak,pss);if(at<60000)continue;if(n==0)start=pss;end=pss;double x=at/60000d;n++;sx+=x;sy+=pss;sxx+=x*x;sxy+=x*pss;}double denominator=n*sxx-sx*sx;return new JSONObject().put("warmupMs",60000).put("sampledProcessPssPeakKiB",peak).put("warmSamples",n).put("firstWarmPssKiB",start).put("lastWarmPssKiB",end).put("warmPssKiBPerMinute",denominator==0?JSONObject.NULL:(n*sxy-sx*sy)/denominator).put("interpretation","variable bounded data capacities, native reallocations, automatic ART/QuickJS GC and lifecycle overlap affect whole-process trend; no explicit GC or leak-free claim from slope alone");}
    private JSONObject report(String status,Throwable error) throws JSONException {ArrayList<Double> latencies=new ArrayList<>(own.latencies);Collections.sort(latencies);JSONObject latency=new JSONObject().put("sampleCount",latencies.size());if(!latencies.isEmpty())latency.put("p50",latencies.get((latencies.size()-1)/2)).put("p95",latencies.get((int)Math.floor((latencies.size()-1)*0.95))).put("max",latencies.get(latencies.size()-1));JSONObject report=new JSONObject().put("version","0.2.5").put("status",status).put("elapsedMs",SystemClock.elapsedRealtime()-own.start).put("requestedDurationMs",own.duration).put("passed",status.equals("completed")&&own.errors.length()==0?1:0).put("charts",3).put("generations",own.generations).put("ticks",own.ticks).put("appends",own.appends).put("corrections",own.corrections).put("prepareRequests",own.prepares).put("terminalCallbacks",own.callbacks).put("readyCancels",own.cancelled).put("staleRejections",own.stale).put("chartSourcesCreated",own.created).put("chartSourcesClosed",own.closed).put("foregroundHeartbeatMaxMs",own.heartbeatMax/1e6).put("operationLatencyMs",latency).put("memoryTrend",trend()).put("samples",own.samples).put("events",own.events).put("jobs",own.jobs).put("errors",own.errors).put("physicalDevice",false).put("method","three attached native Canvas Views;100ms stream/correction work, rotating8s initial prepare success/readycancel/stale,16ms foreground heartbeat,10s PSS/RSS/runtime handle samples; session data retained across Activity recreation; root adb drives lifecycle; no explicit GC");if(error!=null)report.put("failed",true).put("error",error.toString());return report;}
    private void finish(Throwable error,String status){if(context==null||finishing)return;finishing=true;running=false;handler.removeCallbacksAndMessages(null);try{if(error!=null)own.errors.put(error.toString());event(status);for(int i=0;i<3;i++){if(views[i]!=null){host.removeView(views[i]);views[i]=null;}if(engines[i]!=null){engines[i].close();engines[i]=null;own.closed++;}}if(status.equals("completed")&&error==null){awaitTerminalCleanup(SystemClock.elapsedRealtime()+5000);return;}deliver(status,error,false);}catch(Throwable cleanupError){deliver("failed",cleanupError,false);}}
    private void awaitTerminalCleanup(long deadline){if(context==null)return;try{JSONObject runtime=diagnosticEngine.runtimeMetrics();boolean callbacks=own.callbacks==own.prepares,handles=runtime.getLong("processLiveNativeHandles")==1;if(callbacks&&handles){deliver("completed",null,true);return;}if(SystemClock.elapsedRealtime()>=deadline){Throwable error=new AssertionError("Terminal cleanup did not settle: callbacks"+own.callbacks+"/"+own.prepares+" liveHandles"+runtime.getLong("processLiveNativeHandles"));own.errors.put(error.toString());deliver("failed",error,false);return;}handler.postDelayed(()->awaitTerminalCleanup(deadline),10);}catch(Throwable error){deliver("failed",error,false);}}
    private void deliver(String status,Throwable error,boolean cleanupSettled){if(context==null)return;try{JSONObject report=report(status,error).put("terminalCleanupSettled",cleanupSettled).put("expectedProcessHandlesAfterSourceClose",1).put("processRuntimeAfterSourceClose",diagnosticEngine.runtimeMetrics());write("android-soak-progress.json",report.toString());if(status.equals("completed")||error!=null)write("android-soak-validation.json",report.toString());completion.accept(report);}catch(Throwable cleanupError){android.util.Log.e("AsterSoak","Cleanup/report failed",cleanupError);}finally{context=null;}}
    private void write(String name,String text){try(FileOutputStream out=context.openFileOutput(name,Context.MODE_PRIVATE)){out.write(text.getBytes("UTF-8"));}catch(IOException error){throw new IllegalStateException(error);}}
}
